import cadquery as cq

# Define the coordinate system transformation
def transform_coordinate_system(angle_z, translation_vector):
    return cq.Workplane("XY").rotate((0, 0, 0), (0, 0, 1), angle_z).translate(translation_vector)

# Create the sketch
def create_sketch(length, width):
    return cq.Workplane("XY").moveTo(0, 0).lineTo(length, 0).lineTo(length, width).lineTo(0, width).close()

# Extrude the sketch
def extrude_sketch(sketch, extrude_depth):
    return sketch.extrude(extrude_depth)

# Define the parameters
length = 0.75
width = 0.0962
height = 0.0098
angle_z = -90.0
translation_vector = (0.0, 0.0098, 0.0)

# Create the final model
r = transform_coordinate_system(angle_z, translation_vector).add(create_sketch(length, width).extrude(height))

# Display the final model
